        int T = sc.nextInt(); // target color
        int[][] grid = new int[R][C];
        for (int i = 0; i < R; i++)
            for (int j = 0; j < C; j++)
                grid[i][j] = sc.nextInt();

        int maxBudget = 5;
        int ans = 0;
        int[][] dist = new int[R][C];
        int[] dr = {-1,1,0,0}, dc = {0,0,-1,1};

        for (int si = 0; si < R; si++) {
            for (int sj = 0; sj < C; sj++) {
                for (int[] d : dist) Arrays.fill(d, Integer.MAX_VALUE);
                Deque<int[]> dq = new ArrayDeque<>();
                dist[si][sj] = (grid[si][sj] == T) ? 0 : 1;
                dq.addFirst(new int[]{si, sj});
                int count = 0;
                while (!dq.isEmpty()) {
                    int[] cur = dq.pollFirst();
                    int r = cur[0], c = cur[1], cost = dist[r][c];
                    if (cost > maxBudget) continue;
                    count++;
                    for (int d = 0; d < 4; d++) {
                        int nr = r+dr[d], nc = c+dc[d];
                        if (nr<0||nr>=R||nc<0||nc>=C) continue;
                        int nc2 = cost + (grid[nr][nc]==T?0:1);
                        if (nc2 < dist[nr][nc]) {
                            dist[nr][nc] = nc2;
                            if (grid[nr][nc]==T) dq.addFirst(new int[]{nr,nc});
                            else dq.addLast(new int[]{nr,nc});
                        }
                    }
                }
                ans = Math.max(ans, count);
            }
        }
        System.out.println(ans);
    }
