import java.io.*;
import java.util.*;

/*
 * AOJ-like problem:
 * Given an H x W grid of colors (integers), choose a target color c.
 * You may repaint up to 5 times. In one repaint, choose a color x and repaint
 * the whole currently connected component containing the top-left cell (0,0)
 * into color x; after repainting, it merges with adjacent cells of color x.
 * Find the maximum possible size of that connected component after at most 5 repaints,
 * ending with target color c.
 *
 * Standard state-compression DP:
 * - Compress the grid into connected components of same color.
 * - Build component graph.
 * - DP over (set of absorbed components, remaining steps) with memoization.
 *
 * Since only 5 moves are allowed, reachable frontier stays small enough.
 */
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int H, W, C;
    static int[][] grid;

    static int compCnt;
    static int[] compColor;
    static int[] compSize;
    static long[] compBit; // only works if component count <= 63/64; for this problem it is enough in typical constraints
    static ArrayList<Integer>[] graph;
    static int[][] compId;

    static int startComp;
    static int targetColor;

    static HashMap<Long, Integer> memo;

    static long encode(long mask, int steps, int color) {
        // steps <= 5, color small enough
        // Use a mixed hash key
        long key = mask;
        key ^= ((long) steps) << 56;
        key ^= ((long) color) << 48;
        return key;
    }

    static int dfs(long mask, int steps, int currentColor) {
        long key = encode(mask, steps, currentColor);
        Integer cached = memo.get(key);
        if (cached != null) return cached;

        int currentSize = sizeOfMask(mask);
        int best = (currentColor == targetColor) ? currentSize : 0;
        if (steps == 0) {
            memo.put(key, best);
            return best;
        }

        // Collect neighboring colors and the components that would be absorbed for each color.
        HashMap<Integer, Long> addByColor = new HashMap<>();
        for (int i = 0; i < compCnt; i++) {
            if (((mask >> i) & 1L) == 0) continue;
            for (int to : graph[i]) {
                if (((mask >> to) & 1L) != 0) continue;
                int col = compColor[to];
                long old = addByColor.getOrDefault(col, 0L);
                addByColor.put(col, old | (1L << to));
            }
        }

        for (Map.Entry<Integer, Long> e : addByColor.entrySet()) {
            int nextColor = e.getKey();
            long nextMask = mask;

            // Repeatedly absorb all connected boundary components of nextColor.
            ArrayDeque<Integer> q = new ArrayDeque<>();
            long firstAdd = e.getValue();
            long tmp = firstAdd;
            while (tmp != 0) {
                int b = Long.numberOfTrailingZeros(tmp);
                q.add(b);
                tmp &= tmp - 1;
            }
            nextMask |= firstAdd;

            while (!q.isEmpty()) {
                int v = q.poll();
                for (int to : graph[v]) {
                    if (((nextMask >> to) & 1L) != 0) continue;
                    if (compColor[to] == nextColor) {
                        nextMask |= (1L << to);
                        q.add(to);
                    }
                }
            }

            best = Math.max(best, dfs(nextMask, steps - 1, nextColor));
        }

        memo.put(key, best);
        return best;
    }

    static int sizeOfMask(long mask) {
        int sum = 0;
        while (mask != 0) {
            int b = Long.numberOfTrailingZeros(mask);
            sum += compSize[b];
            mask &= mask - 1;
        }
        return sum;
    }

    static void buildComponents() {
        compId = new int[H][W];
        for (int i = 0; i < H; i++) Arrays.fill(compId[i], -1);

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        ArrayList<Integer> colorList = new ArrayList<>();
        ArrayList<Integer> sizeList = new ArrayList<>();

        compCnt = 0;
        for (int r = 0; r < H; r++) {
            for (int c = 0; c < W; c++) {
                if (compId[r][c] != -1) continue;
                int color = grid[r][c];
                ArrayDeque<int[]> q = new ArrayDeque<>();
                q.add(new int[]{r, c});
                compId[r][c] = compCnt;
                int sz = 0;
                while (!q.isEmpty()) {
                    int[] cur = q.poll();
                    int x = cur[0], y = cur[1];
                    sz++;
                    for (int k = 0; k < 4; k++) {
                        int nx = x + dr[k], ny = y + dc[k];
                        if (0 <= nx && nx < H && 0 <= ny && ny < W &&
                                compId[nx][ny] == -1 && grid[nx][ny] == color) {
                            compId[nx][ny] = compCnt;
                            q.add(new int[]{nx, ny});
                        }
                    }
                }
                colorList.add(color);
                sizeList.add(sz);
                compCnt++;
            }
        }

        compColor = new int[compCnt];
        compSize = new int[compCnt];
        for (int i = 0; i < compCnt; i++) {
            compColor[i] = colorList.get(i);
            compSize[i] = sizeList.get(i);
        }

        graph = new ArrayList[compCnt];
        for (int i = 0; i < compCnt; i++) graph[i] = new ArrayList<>();

        HashSet<Long> edges = new HashSet<>();
        for (int r = 0; r < H; r++) {
            for (int c = 0; c < W; c++) {
                int a = compId[r][c];
                if (r + 1 < H) {
                    int b = compId[r + 1][c];
                    if (a != b) {
                        int x = Math.min(a, b), y = Math.max(a, b);
                        long code = (((long) x) << 32) | (y & 0xffffffffL);
                        if (edges.add(code)) {
                            graph[a].add(b);
                            graph[b].add(a);
                        }
                    }
                }
                if (c + 1 < W) {
                    int b = compId[r][c + 1];
                    if (a != b) {
                        int x = Math.min(a, b), y = Math.max(a, b);
                        long code = (((long) x) << 32) | (y & 0xffffffffL);
                        if (edges.add(code)) {
                            graph[a].add(b);
                            graph[b].add(a);
                        }
                    }
                }
            }
        }

        startComp = compId[0][0];
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            H = fs.nextInt();
            W = fs.nextInt();
            C = fs.nextInt();
            if (H == 0 && W == 0 && C == 0) break;

            grid = new int[H][W];
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    grid[i][j] = fs.nextInt();
                }
            }

            buildComponents();

            targetColor = C;
            memo = new HashMap<>();
            long startMask = 1L << startComp;
            int answer = dfs(startMask, 5, compColor[startComp]);

            out.append(answer).append('\n');
        }

        System.out.print(out.toString());
    }
}

