int comp_size[MAX_N * MAX_M];
int cur_comp;

int dx[4] = {1, -1, 0, 0};
int dy[4] = {0, 0, 1, -1};

void bfs(int sx, int sy, char target) {
    queue<pair<int,int>> q;
    q.push({sx, sy});
    visited[sx][sy] = 1;
    comp_id[sx][sy] = cur_comp;
    int cnt = 0;
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        cnt++;
        for (int d = 0; d < 4; d++) {
            int nx = x + dx[d];
            int ny = y + dy[d];
            if (nx < 0 || nx >= H || ny < 0 || ny >= W) continue;
            if (visited[nx][ny]) continue;
            if (grid[nx][ny] != target) continue;
            visited[nx][ny] = 1;
            comp_id[nx][ny] = cur_comp;
            q.push({nx, ny});
        }
    }
    comp_size[cur_comp] = cnt;
    cur_comp++;
}

