    // We can change up to K cells to target color.
    // The best we can do is take the largest component of target color,
    // and possibly merge adjacent components by changing cells.
    // Since K <= 5, we can do BFS from each target component border
    // and consider changing cells to connect.

    // First, find all components of target color
    vector<int> target_comps;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == target && comp_id[i][j] != -1) {
                target_comps.push_back(comp_id[i][j]);
            }
