    // We'll do BFS limited to K steps from the border of each target component
    // and collect reachable non-target cells, then see how many components we can connect.

    // Since H,W up to 1000, total cells up to 1e6, K <= 5, we can afford BFS per component if we are careful.
    // But there could be many components. Instead, we can do multi-source BFS from all target cells
    // with distance = number of changes needed to reach a cell.
    // Then for each cell, if distance <= K, we can potentially include it.
    // However, we also need to consider that changing a cell can connect multiple components.
    // Since K is small, we can do BFS from each target component border with limited depth.

    // Alternative: For each cell, compute distance to nearest target color cell (in terms of number of non-target cells to change).
    // Then we can find connected regions reachable within K changes.
    // But the problem asks for largest unified panel after changes, meaning we can change cells to target,
    // and then panels of same color fuse. So we want the largest connected component of target color after changing up to K cells.

    // Since K <= 5, we can simply try changing any set of up to K cells? No, too many.

    // Better approach: For each cell, compute min changes to connect it to some target component.
    // But we need to consider merging of components.

    // Since K is very small (<=5), we can do BFS from all target cells simultaneously,
    // where moving into a non-target cell costs 1 (change needed), and moving into target cell costs 0.
    // Then the distance to a cell is the minimum number of changes needed to make a path from some target cell to that cell.
    // After we have distances, we can consider all cells with distance <= K, and the largest connected component
    // of such cells (including original target cells) will be the answer.
    // But careful: if we change a cell, it becomes target, so it can connect adjacent target cells.
    // This BFS distance approach works because we are essentially building a union of all cells reachable with <= K changes.

    // Let's implement multi-source 0-1 BFS (or Dijkstra with small weights).
    // Since edge weight is 0 if moving to target, 1 if moving to non-target, we can use deque BFS.

    const int INF = 1e9;
    vector<vector<int>> dist(H, vector<int>(W, INF));
    deque<pair<int,int>> dq;

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == target) {
                dist[i][j] = 0;
                dq.push_front({i, j});
            }
        }
    }

    while (!dq.empty()) {
        auto [x, y] = dq.front(); dq.pop_front();
        for (int d = 0; d < 4; d++) {
            int nx = x + dx[d];
            int ny = y + dy[d];
            if (nx < 0 || nx >= H || ny < 0 || ny >= W) continue;
            int w = (grid[nx][ny] == target ? 0 : 1);
            if (dist[x][y] + w < dist[nx][ny]) {
                dist[nx][ny] = dist[x][y] + w;
                if (w == 0) dq.push_front({nx, ny});
                else dq.push_back({nx, ny});
            }
        }
    }

    // Now find largest connected component of cells with dist <= K
    vector<vector<int>> visited2(H, vector<int>(W, 0));
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (dist[i][j] <= K && !visited2[i][j]) {
                // BFS to count component size
                queue<pair<int,int>> q;
                q.push({i, j});
                visited2[i][j] = 1;
                int cnt = 0;
                while (!q.empty()) {
                    auto [x, y] = q.front(); q.pop();
                    cnt++;
                    for (int d = 0; d < 4; d++) {
                        int nx = x + dx[d];
                        int ny = y + dy[d];
                        if (nx < 0 || nx >= H || ny < 0 || ny >= W) continue;
                        if (visited2[nx][ny]) continue;
                        if (dist[nx][ny] <= K) {
                            visited2[nx][ny] = 1;
                            q.push({nx, ny});
                        }
                    }
                }
                answer = max(answer, cnt);
            }
        }
    }

    cout << answer << "\n";
    return 0;
}

