    for (int i = 0; i < H; ++i) for (int j = 0; j < W; ++j) if (compId[i][j] == -1) {
        int col = g[i][j];
        queue<pair<int,int>> q;
        q.push({i,j});
        compId[i][j] = n;
        int sz = 0;
        while (!q.empty()) {
            auto [r,c] = q.front(); q.pop();
            ++sz;
            for (int k = 0; k < 4; ++k) {
                int nr = r + dr[k], nc = c + dc[k];
                if (0 <= nr && nr < H && 0 <= nc && nc < W && compId[nr][nc] == -1 && g[nr][nc] == col) {
                    compId[nr][nc] = n;
                    q.push({nr,nc});
                }
            }
        }
        compColor.push_back(col);
        compSize.push_back(sz);
        ++n;
    }

    vector<vector<int>> adj(n);
    for (int i = 0; i < H; ++i) for (int j = 0; j < W; ++j) {
        int u = compId[i][j];
        for (int k = 0; k < 4; ++k) {
            int ni = i + dr[k], nj = j + dc[k];
            if (0 <= ni && ni < H && 0 <= nj && nj < W) {
                int v = compId[ni][nj];
                if (u != v) adj[u].push_back(v);
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        sort(adj[i].begin(), adj[i].end());
        adj[i].erase(unique(adj[i].begin(), adj[i].end()), adj[i].end());
    }

    int B = (n + 63) >> 6;
    auto makeBits = [&](int s) {
        DynBits b; b.a.assign(B, 0);
        b.a[s >> 6] |= 1ULL << (s & 63);
        return b;
    };
    auto testBit = [&](DynBits const& b, int i) -> bool {
        return (b.a[i >> 6] >> (i & 63)) & 1ULL;
    };
    auto addBit = [&](DynBits &b, int i) {
        b.a[i >> 6] |= 1ULL << (i & 63);
    };
    auto bitCount = [&](DynBits const& b) {
        int s = 0;
        for (auto x : b.a) s += __builtin_popcountll(x);
        return s;
    };

    struct Key {
        DynBits bits;
        int color, depth;
        bool operator==(Key const& o) const {
            return color == o.color && depth == o.depth && bits == o.bits;
        }
    };
    struct KeyHash {
        size_t operator()(Key const& k) const {
            size_t h = HashDynBits()(k.bits);
            h = h * 1000003ULL ^ std::hash<int>()(k.color);
            h = h * 1000003ULL ^ std::hash<int>()(k.depth);
            return h;
        }
    };

    unordered_map<Key, int, KeyHash> memo;

    function<int(const DynBits&, int, int, int)> dfs = [&](const DynBits& state, int color, int depth, int curSize) -> int {
        Key key{state, color, depth};
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;

        int best = (color == T ? curSize : 0);
        if (depth == 5) {
            memo[key] = best;
            return best;
        }

        // For each next color, absorb all adjacent components of that color.
        vector<char> seenColor(C, 0);
        for (int nc = 0; nc < C; ++nc) {
            if (nc == color) continue;
            DynBits ns = state;
            int add = 0;
            bool any = false;
            for (int u = 0; u < n; ++u) if (testBit(state, u)) {
                for (int v : adj[u]) if (!testBit(ns, v) && compColor[v] == nc) {
                    addBit(ns, v);
                    add += compSize[v];
                    any = true;
                }
            }
            if (!any) continue;

            // Repeatedly absorb newly adjacent same-color components (same nc), because after merging,
            // the enlarged region touches more nc-components and they also merge immediately.
            bool changed = true;
            while (changed) {
                changed = false;
                for (int u = 0; u < n; ++u) if (testBit(ns, u)) {
                    for (int v : adj[u]) if (!testBit(ns, v) && compColor[v] == nc) {
                        addBit(ns, v);
                        add += compSize[v];
                        changed = true;
                    }
                }
            }

            best = max(best, dfs(ns, nc, depth + 1, curSize + add));
        }

        memo[key] = best;
        return best;
    };

    int ans = 0;
    for (int s = 0; s < n; ++s) {
        DynBits st = makeBits(s);
        ans = max(ans, dfs(st, compColor[s], 0, compSize[s]));
    }

    cout << ans << '\n';
    return 0;
}

