#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXH 55
#define MAXW 55
#define MAXN 2600
#define INF 1000000000

typedef struct {
    int y, x;
} Point;

int H, W, C, targetColor;
int grid[MAXH][MAXW];

/* component data */
int compId[MAXH][MAXW];
int compColor[MAXN];
int compSize[MAXN];
int compCount;

/* adjacency between components */
unsigned char adj[MAXN][MAXN];

/* for BFS */
Point q[MAXH * MAXW];

/* DP memo:
   state = (component, remaining shocks, current color)
   value = maximum size obtainable including this component
*/
int memo[MAXN][6][11];
unsigned char vis[MAXN][6][11];

int dy[4] = {-1, 1, 0, 0};
int dx[4] = {0, 0, -1, 1};

void build_components() {
    int y, x, i;
    compCount = 0;
    memset(compId, -1, sizeof(compId));

    for (y = 0; y < H; y++) {
        for (x = 0; x < W; x++) {
            if (compId[y][x] != -1) continue;

            int color = grid[y][x];
            int head = 0, tail = 0;
            q[tail++] = (Point){y, x};
            compId[y][x] = compCount;
            int sz = 0;

            while (head < tail) {
                Point p = q[head++];
                sz++;
                for (i = 0; i < 4; i++) {
                    int ny = p.y + dy[i];
                    int nx = p.x + dx[i];
                    if (ny < 0 || ny >= H || nx < 0 || nx >= W) continue;
                    if (compId[ny][nx] != -1) continue;
                    if (grid[ny][nx] != color) continue;
                    compId[ny][nx] = compCount;
                    q[tail++] = (Point){ny, nx};
                }
            }

            compColor[compCount] = color;
            compSize[compCount] = sz;
            compCount++;
        }
    }

    memset(adj, 0, sizeof(adj));
    for (y = 0; y < H; y++) {
        for (x = 0; x < W; x++) {
            int a = compId[y][x];
            for (i = 0; i < 4; i++) {
                int ny = y + dy[i];
                int nx = x + dx[i];
                if (ny < 0 || ny >= H || nx < 0 || nx >= W) continue;
                int b = compId[ny][nx];
                if (a != b) adj[a][b] = 1;
            }
        }
    }
}

/*
Let f(v, k, col) be the maximum size of a connected fused panel obtainable
starting from component v, when the currently fused region has color col and
we may still change color at most k times.

The region must always remain connected and contain v.
If a neighboring component has the same color as current color, it can be
absorbed for free, and then recursively expanded further with same state.
If we still have shocks left, we may recolor the whole current region to some
neighbor's color and absorb that neighbor, spending 1 shock.

Since k <= 5 and colors are small, memoized DFS is enough.
*/
int solve_state(int v, int k, int col) {
    if (vis[v][k][col]) return memo[v][k][col];
    vis[v][k][col] = 1;

    int best = compSize[v];
    int u;

    /* absorb same-color neighbors for free */
    for (u = 0; u < compCount; u++) {
        if (!adj[v][u]) continue;
        if (compColor[u] != col) continue;
        int cand = compSize[v] + solve_state(u, k, col);
        if (cand > best) best = cand;
    }

    /* recolor once to neighbor's color and absorb */
    if (k > 0) {
        for (u = 0; u < compCount; u++) {
            if (!adj[v][u]) continue;
            int ncol = compColor[u];
            if (ncol == col) continue;
            int cand = compSize[v] + solve_state(u, k - 1, ncol);
            if (cand > best) best = cand;
        }
    }

    memo[v][k][col] = best;
    return best;
}

int main(void) {
    int i, j;

    /* Assumed input format:
       H W C T
       H lines each with W integers/colors
    */
    if (scanf("%d %d %d %d", &H, &W, &C, &targetColor) != 4) return 0;

    for (i = 0; i < H; i++) {
        for (j = 0; j < W; j++) {
            scanf("%d", &grid[i][j]);
        }
    }

    build_components();
    memset(vis, 0, sizeof(vis));

    int ans = 0;

    for (i = 0; i < compCount; i++) {
        int need = (compColor[i] == targetColor ? 0 : 1);
        if (need <= 5) {
            int cur = solve_state(i, 5 - need, targetColor);
            if (cur > ans) ans = cur;
        }
    }

    printf("%d\n", ans);
    return 0;
}
